class UnitServer(Server):
    def __init__(self, clients):
        super().__init__(clients)
        if self.R != 1.0:
            raise ValueError("Server rate must be 1.0 for a unit server.")

    def get_job_execution_time(self, job_release_time, job_deadline):
        # For a unit server, the execution time is the interval duration
        return job_deadline - job_release_time

class EDFServer(Server):
    def schedule_clients(self, current_time):
        ready_client_jobs = [job for job in self.get_ready_jobs(current_time) if job.client_server == self]
        if not ready_client_jobs:
            return None # No clients to run
        earliest_deadline_job = min(ready_client_jobs, key=lambda job: job.absolute_deadline)
        return earliest_deadline_job

def is_valid_packing(server_set, packing):
    # packing is a list of lists, where each inner list is a subset of server_set
    all_servers_in_packing = [server for subset in packing for server in subset]
    if set(all_servers_in_packing) != set(server_set):
        return False # Not a partition

    subset_rates = []
    for subset in packing:
        subset_rate = sum(server.R for server in subset)
        if subset_rate > 1.0:
            return False # Subset rate exceeds 1
        subset_rates.append(subset_rate)

    for i in range(len(subset_rates)):
        for j in range(i + 1, len(subset_rates)):
            if subset_rates[i] + subset_rates[j] <= 1.0:
                return False # Condition R(Gamma_i) + R(Gamma_j) > 1 not met
    return True

def is_packed_server_set(server_set):
    n = len(server_set)
    if n <= 1:
        return True
    for i in range(n):
        for j in range(i + 1, n):
            if server_set[i].R + server_set[j].R <= 1.0:
                return False
    return True

def check_packed_set_rate_condition(server_set):
    n = len(server_set)
    total_rate = sum(server.R for server in server_set)

    is_all_unit = all(server.R == 1.0 for server in server_set)

    if is_all_unit:
        # If all are unit servers, R(Gamma) = n. If n is positive integer, this is fine.
        # But the lemma assumes 'not all unit servers'.
        pass

    if total_rate > 0 and total_rate == int(total_rate) and not is_all_unit:
        if n < 3:
            print(f"Lemma IV.2 violated: Packed set with R(Gamma)={total_rate} (integer), not all unit, but |Gamma|={n} < 3.")
            return False
    return True

def check_packed_utilization_bound(server_set):
    n = len(server_set)
    if n < 2:
        return True # Lemma applies for n >= 2

    total_rate = sum(server.R for server in server_set)

    # Check if the condition R(Gamma) > n/2 holds
    if total_rate <= n / 2.0:
        print(f"Lemma V.1 violated: Packed set with n={n}, R(Gamma)={total_rate}, but R(Gamma) <= n/2.")
        return False
    return True
